(()=>{
 const en=document.documentElement.lang==='en',t=(a,b)=>en?b:a;
 // Pixel positions read from the supplied map. These locate building footprints, not verified entrances.
 const points=[['R16','Arts Building',1398,685],['R18','Strathcona Building',1435,637],['R13','Poynting Building',1428,865],['Y3','Winifred Hackett Building',1059,863],['Y9','Computer Science',1044,761],['R25','Munrow Lecture Theatre',1258,501],['R6','Aston Webb – Great Hall',1316,879],['R7','Aston Webb – Student Hub',1343,888],['R5','Aston Webb – B Block',1287,846],['R30','Main Library',1282,640],['R32','Teaching and Learning Building',1308,577]];
 const starts=[['University Station',1015,653],['North Gate',1380,508],['South Gate',1314,1012],['East Gate',1524,785],['West Gate',1014,715],['Grange Road Gate',1185,996]];
 const section=document.getElementById('map');section.querySelectorAll('a').forEach(a=>{if(a.querySelector('img'))a.hidden=true;});
 const wrap=document.createElement('div');wrap.innerHTML=`<h3>${t('校园建筑与入口交互地图','Interactive campus buildings and entrances')}</h3><p>${t('拖动地图平移，使用滚轮、双指或按钮放大。点击建筑名选择终点，蓝色入口名选择起点。标记对应建筑轮廓，未核验实际入口。','Drag to pan; use wheel, pinch or buttons to zoom. Select a building label as destination or a blue entrance label as origin. Markers locate footprints, not verified entrances.')}</p><div class="campus-tools"><button type="button" id="campusIn">＋</button><button type="button" id="campusOut">−</button><button type="button" id="campusReset">${t('重置视图','Reset view')}</button><span id="campusZoom" role="status"></span></div><svg id="campusCanvas" viewBox="780 360 960 720" role="img" aria-label="${t('可拖动缩放的校园地图','Pannable and zoomable campus map')}" style="width:100%;height:620px;background:#e8ece3;touch-action:none;border-radius:12px"><image href="assets/campus-map.webp" width="1786" height="1263"/>${points.map(p=>`<g class="campus-building" data-code="${p[0]}" tabindex="0" role="button" aria-label="${p[0]} ${p[1]}"><circle cx="${p[2]}" cy="${p[3]}" r="6" fill="#145b36"/><text x="${p[2]+9}" y="${p[3]-9}">${p[0]} · ${p[1]}</text></g>`).join('')}${starts.map((p,i)=>`<g class="campus-start" data-start="${i}" tabindex="0" role="button" aria-label="${p[0]}"><circle cx="${p[1]}" cy="${p[2]}" r="7" fill="#145ca0"/><text x="${p[1]+10}" y="${p[2]+18}">${p[0]}</text></g>`).join('')}</svg><div class="route-card"><div class="two-col"><label>${t('校园到达点','Campus arrival point')}<select id="campusStart">${starts.map((s,i)=>`<option value="${i}">${s[0]}</option>`).join('')}<option value="bus">${t('周边公交站（手动指定）','Nearby bus stop (enter name)')}</option></select></label><label>${t('目标建筑','Destination building')}<select id="campusDestination">${points.map(p=>`<option value="${p[0]}">${p[0]} · ${p[1]}</option>`).join('')}</select></label></div><label id="campusBusLabel" hidden>${t('公交站名或站点地址（请区分方向）','Bus stop name or address (check direction)')}<input id="campusBus" maxlength="150" placeholder="${t('例如运营商公布的站名','Use the operator’s stop name')}"></label><p id="campusSelection" role="status"></p><div class="campus-navigation-actions"><a class="primary" href="https://www.birmingham.ac.uk/contact/campus-map" target="_blank" rel="noopener">${t('伯明翰大学官方校园导航','University official campus navigation')} ↗</a><a class="primary" id="campusDirections" target="_blank" rel="noopener">${t('在 Google Maps 中规划步行','Plan walking directions in Google Maps')} ↗</a></div><p>${t('站点与校门到建筑的实际路径交由外部地图查询。本页不提供未经验证的转向指令或步行时间；外部地图会收到所选起终点，且可能需要确认匹配地点。无障碍通行、开门时间和入口请另外确认。','Actual paths from stops or gates to buildings are requested in the external map. This page does not invent turn instructions or walking times. The external map receives the selected endpoints and may require place confirmation. Check accessibility, opening hours and entrances separately.')}</p></div>`;
 section.append(wrap);const css=document.createElement('style');css.textContent='.campus-navigation-actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;align-items:stretch}.campus-navigation-actions a.primary{display:flex!important;align-items:center;justify-content:center;text-align:center;padding:15px 18px;text-decoration:none;min-width:0;line-height:1.5;font-size:14px;white-space:normal}.campus-tools{display:flex;gap:10px;align-items:center;margin:15px 0}.campus-tools button{padding:10px 16px;background:white;border:1px solid #aaa;border-radius:6px;cursor:pointer}#campusCanvas{cursor:grab}#campusCanvas text{font:600 12px sans-serif;paint-order:stroke;stroke:white;stroke-width:4px;stroke-linejoin:round;fill:#103a2d}.campus-start text{fill:#064f91}.campus-building,.campus-start{cursor:pointer}.campus-building:focus text,.campus-start:focus text{fill:#ac401b}.campus-tools+svg:active{cursor:grabbing}#campusDirections{display:inline-block;text-decoration:none}';document.head.append(css);
 const $=id=>document.getElementById(id),svg=$('campusCanvas');let box=[780,360,960,720],drag,dist;
 function render(){svg.setAttribute('viewBox',box.join(' '));$('campusZoom').textContent=Math.round(960/box[2]*100)+'%';}
 function zoom(f){const w=Math.max(160,Math.min(1786,box[2]*f)),h=w*.75;box=[box[0]+(box[2]-w)/2,box[1]+(box[3]-h)/2,w,h];render();}
 $('campusIn').onclick=()=>zoom(.75);$('campusOut').onclick=()=>zoom(1.33);$('campusReset').onclick=()=>{box=[780,360,960,720];render();};svg.addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY>0?1.12:.89);},{passive:false});
 const pointers=new Map();svg.onpointerdown=e=>{pointers.set(e.pointerId,[e.clientX,e.clientY]);svg.setPointerCapture(e.pointerId);drag=[e.clientX,e.clientY];};svg.onpointermove=e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,[e.clientX,e.clientY]);if(pointers.size===2){const a=[...pointers.values()],d=Math.hypot(a[0][0]-a[1][0],a[0][1]-a[1][1]);if(dist)zoom(dist/d);dist=d;drag=null;}else if(drag){const r=svg.getBoundingClientRect();box[0]-=(e.clientX-drag[0])*box[2]/r.width;box[1]-=(e.clientY-drag[1])*box[3]/r.height;drag=[e.clientX,e.clientY];render();}};svg.onpointerup=svg.onpointercancel=e=>{pointers.delete(e.pointerId);drag=null;dist=null;};
 function selection(){const p=points.find(p=>p[0]===$('campusDestination').value),isBus=$('campusStart').value==='bus';$('campusBusLabel').hidden=!isBus;const origin=isBus?$('campusBus').value.trim():starts[Number($('campusStart').value)][0];$('campusSelection').textContent=(origin||t('请填写公交站','Enter a bus stop'))+' → '+p[0]+' · '+p[1];const u=new URL('https://www.google.com/maps/dir/');u.searchParams.set('api','1');u.searchParams.set('origin',origin+', University of Birmingham, Birmingham, UK');u.searchParams.set('destination',p[1]+', University of Birmingham, UK');u.searchParams.set('travelmode','walking');$('campusDirections').href=u;$('campusDirections').onclick=e=>{if(isBus&&!origin){e.preventDefault();$('campusBus').focus();}};}
 $('campusStart').onchange=selection;$('campusDestination').onchange=selection;$('campusBus').oninput=selection;
 svg.querySelectorAll('g').forEach(g=>{const activate=()=>{if(g.dataset.code){$('campusDestination').value=g.dataset.code;const main=$('building');if(main.querySelector(`option[value="${g.dataset.code}"]`)){main.value=g.dataset.code;main.dispatchEvent(new Event('change'));}}else $('campusStart').value=g.dataset.start;selection();};g.onclick=activate;g.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();activate();}};});
 $('building').addEventListener('change',()=>{if(points.some(p=>p[0]===$('building').value))$('campusDestination').value=$('building').value;selection();});if(points.some(p=>p[0]===$('building').value))$('campusDestination').value=$('building').value;render();selection();
})();

